import { useEffect, useRef, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { Link, useParams } from 'react-router';
import { ArrowDown, ArrowLeft, ArrowRight, ArrowUp, BookOpen, Check, ChevronLeft, ChevronRight, CircleCheck, Copy, ExternalLink, FileText, FolderOpen, GraduationCap, Layers3, LockKeyhole, Plus, RefreshCw, Save, Trash2, Upload, Users, X } from 'lucide-react';
import { ApiError, apiJson } from './api';
import { AuthenticatedArea, LogoutButton, useAuth } from './auth';
import { CourseUnitContent, MarkdownContent } from './course-content';
import type { CourseAsset } from './course-content';
import type { CourseDocument, CourseUnit } from '../server/course-model';

type CourseSummary = { id: string; title: string; status: string; revision: number; publishedVersion: number | null };
type CourseRecord = { id: string; title: string; status: string; draft_revision: number; draft: CourseDocument };
type Version = { id: string; version: number; published_at: string };
type CourseOrg = { id: string; name: string; kind: string; branding: Record<string, unknown> };
type StudentCourse = { id: string; enrollmentId: string; title: string; description: string; status: string; version: number };
type StudentDetail = { enrollmentId: string; versionId: string; version: number; status: string; document: CourseDocument; assets: CourseAsset[] };
const failure = (error: unknown) => error instanceof ApiError ? error.message : 'Não foi possível concluir esta ação. Tente novamente.';
const makeId = (prefix: string) => `${prefix}-${crypto.randomUUID()}`;
const formatDate = (value: string) => new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short', timeZone: 'America/Sao_Paulo' }).format(new Date(value));
const courseStatus: Record<string, string> = { draft: 'Rascunho', published: 'Publicado', archived: 'Arquivado' };
function creditLabel(org?: { branding: Record<string, unknown> } | null) { return typeof org?.branding.creditPlural === 'string' ? org.branding.creditPlural : 'créditos'; }
function singularCreditLabel(org?: { branding: Record<string, unknown> } | null) { return typeof org?.branding.creditSingular === 'string' ? org.branding.creditSingular : 'crédito'; }
function newCriterion() { return { id: makeId('criterio'), title: 'Clareza da mensagem', enabled: true, weight: 1, modality: 'both' as const, descriptors: ['A mensagem central ainda precisa ser identificada.', 'A mensagem aparece, com trechos que precisam de organização.', 'A mensagem é clara e apoiada por exemplos pertinentes.', 'A mensagem é precisa e adaptada ao público e ao objetivo.'] as [string, string, string, string] }; }
function newUnit(kind: 'lesson' | 'review'): CourseUnit { return { id: makeId('unidade'), title: kind === 'review' ? 'Nova revisão' : 'Nova aula', kind, chapter: '', mode: 'content', bodyMarkdown: '', instructionMarkdown: 'Apresente uma ideia com início, desenvolvimento e conclusão.', checklist: [], references: [], assetIds: [], prerequisites: [], activity: { maximumSeconds: kind === 'review' ? 300 : 30, acceptedMedia: ['audio', 'video'], scenario: 'one_on_one', criteria: [newCriterion()] }, studyCreditGrant: kind === 'review' ? 5 : 1, requiresEvaluation: true }; }
function reorder<T>(items: T[], index: number, direction: number) { const target = index + direction; if (target < 0 || target >= items.length) return items; const next = [...items]; [next[index], next[target]] = [next[target], next[index]]; return next; }

function CourseDialog({ title, children, close, pending = false }: { title: string; children: ReactNode; close: () => void; pending?: boolean }) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => { const dialog = ref.current; dialog?.showModal(); return () => dialog?.close(); }, []);
  return <dialog ref={ref} className="education-dialog course-dialog" aria-label={title} onCancel={event => { event.preventDefault(); if (!pending) close(); }}><div className="education-dialog-heading"><h2>{title}</h2><button className="icon-button" type="button" aria-label="Fechar janela" disabled={pending} onClick={close}><X size={21} /></button></div>{children}</dialog>;
}
function CourseState({ error, retry, message = 'Carregando os cursos…' }: { error?: string | null; retry: () => void; message?: string }) { return <div className="organization-state" role="status"><RefreshCw size={23} className={error ? '' : 'spinning'} /><h2>{error ? 'Não foi possível carregar este conteúdo.' : message}</h2>{error && <><p>{error}</p><button type="button" className="button button-secondary" onClick={retry}>Tentar novamente</button></>}</div>; }
function EditorGuard({ children }: { children: ReactNode }) { const { user } = useAuth(); return user?.roles.some(role => role === 'org_admin' || role === 'operator') ? children : <section className="access-state container"><LockKeyhole size={28} /><h1>O conteúdo é organizado pela administração.</h1><p>As escolas e os professores acompanham o plano publicado pela organização.</p><Link to="/app" className="button button-primary">Voltar ao meu espaço<ArrowRight size={17} /></Link></section>; }

export function CoursesManagementPage({ central = false }: { central?: boolean }) { const { user } = useAuth(); const school = !central && user?.roles.includes('school') && !user.roles.includes('org_admin'); return <AuthenticatedArea area={central ? 'backoffice' : 'admin'}><>{school ? <SchoolCourseManagement /> : <EditorGuard><CoursesManagement central={central} /></EditorGuard>}</></AuthenticatedArea>; }
function CoursesManagement({ central }: { central: boolean }) {
  const { org: currentOrg } = useAuth();
  const [editorOpen, setEditorOpen] = useState(false); const [orgs, setOrgs] = useState<CourseOrg[]>([]); const [orgId, setOrgId] = useState(''); const [error, setError] = useState<string | null>(null); const [attempt, setAttempt] = useState(0);
  useEffect(() => { if (!central) return; const controller = new AbortController(); setError(null); void apiJson<{ orgs: CourseOrg[] }>('/api/backoffice/orgs', { signal: controller.signal }).then(result => setOrgs(result.orgs.filter(item => item.kind !== 'backoffice'))).catch(loadError => { if (!controller.signal.aborted) setError(failure(loadError)); }); return () => controller.abort(); }, [central, attempt]);
  const org = central ? orgs.find(item => item.id === orgId) : currentOrg;
  return <section className="courses-page container"><div className="organization-heading"><div><span className="eyebrow">{central ? 'CONTEÚDO MATRACA E PARCEIROS' : currentOrg?.name}</span><h1>Uma estrutura para a sua metodologia.</h1><p>Organize conteúdo, práticas e critérios. Publique a versão que seus alunos vão seguir.</p></div><LogoutButton /></div>{central && <div className="wallet-org-picker organization-form"><label>Organização<select aria-label="Organização dos cursos" disabled={editorOpen} value={orgId} onChange={event => setOrgId(event.target.value)}><option value="">Selecione uma organização</option>{orgs.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>{error && <div className="form-error wallet-load-error" role="alert">{error}<button type="button" className="button button-secondary" onClick={() => setAttempt(value => value + 1)}>Tentar novamente</button></div>}</div>}{org ? <CourseCatalog key={org.id} org={org} onEditorChange={setEditorOpen} prefix={central ? `/api/backoffice/courses/${org.id}` : '/api/courses/manage'} /> : <div className="wallet-selection-empty"><BookOpen size={32} /><h2>Selecione o espaço que deseja organizar.</h2><p>Os cursos, versões e materiais ficam separados por organização.</p></div>}</section>;
}
function CourseCatalog({ org, prefix, onEditorChange }: { org: CourseOrg; prefix: string; onEditorChange: (open: boolean) => void }) {
  const [courses, setCourses] = useState<CourseSummary[] | null>(null); const [selected, setSelected] = useState<string | null>(null); const [creating, setCreating] = useState(false); const [error, setError] = useState<string | null>(null); const [version, setVersion] = useState(0);
  useEffect(() => { const controller = new AbortController(); setError(null); void apiJson<{ courses: CourseSummary[] }>(prefix, { signal: controller.signal }).then(result => setCourses(result.courses)).catch(loadError => { if (!controller.signal.aborted) setError(failure(loadError)); }); return () => controller.abort(); }, [prefix, version]);
  useEffect(() => { onEditorChange(Boolean(selected)); return () => onEditorChange(false); }, [selected, onEditorChange]);
  if (selected) return <CourseEditor key={selected} id={selected} prefix={prefix} org={org} back={() => { setSelected(null); setVersion(value => value + 1); }} />;
  return <><div className="course-catalog-heading"><div><h2>Seus programas de ensino</h2><p>Comece com o plano Matraca ou construa a sua própria trilha.</p></div><button className="button button-primary" type="button" onClick={() => setCreating(true)}><Plus size={17} />Criar curso</button></div>{!courses || error ? <CourseState error={error} retry={() => setVersion(value => value + 1)} /> : <div className="course-catalog-grid">{courses.map(item => <button key={item.id} type="button" className="course-catalog-card" onClick={() => setSelected(item.id)}><span className="feature-icon icon-green"><BookOpen size={25} /></span><span className={`organization-status ${item.status === 'published' ? 'active' : 'suspended'}`}>{courseStatus[item.status] ?? item.status}</span><h3>{item.title}</h3><p>{item.publishedVersion ? `Versão ${item.publishedVersion} publicada` : 'Ainda sem publicação'}<br />Rascunho · revisão {item.revision}</p><span className="course-open-label">Abrir editor<ArrowRight size={17} /></span></button>)}</div>}{courses?.length === 0 && <div className="wallet-selection-empty"><Layers3 size={32} /><h2>Seu primeiro curso começa aqui.</h2><p>Adicione módulos, aulas, revisões e os critérios de cada prática.</p></div>}{creating && <CreateCourse prefix={prefix} close={() => setCreating(false)} created={id => { setCreating(false); setSelected(id); }} />}</>;
}
function CreateCourse({ prefix, close, created }: { prefix: string; close: () => void; created: (id: string) => void }) {
  const [title, setTitle] = useState(''); const [baseId, setBaseId] = useState(''); const [bases, setBases] = useState<{ id: string; title: string }[]>([]); const [pending, setPending] = useState(false); const [error, setError] = useState<string | null>(null);
  useEffect(() => { const controller = new AbortController(); void apiJson<{ courses: { id: string; title: string }[] }>('/api/courses/base', { signal: controller.signal }).then(result => setBases(result.courses)).catch(loadError => { if (!controller.signal.aborted) setError(failure(loadError)); }); return () => controller.abort(); }, []);
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setPending(true); setError(null); try { const result = await apiJson<{ course: CourseRecord }>(prefix, { method: 'POST', body: { title: title.trim(), ...(baseId ? { copyBaseCourseId: baseId } : {}) } }); created(result.course.id); } catch (saveError) { setError(failure(saveError)); setPending(false); } }
  return <CourseDialog title="Criar programa de ensino" close={close} pending={pending}><form className="organization-form education-action-form course-form" onSubmit={submit}><label>Nome do curso<input aria-label="Nome do curso" value={title} onChange={event => setTitle(event.target.value)} required maxLength={160} disabled={pending} /></label><label>Ponto de partida<select aria-label="Ponto de partida do curso" value={baseId} onChange={event => setBaseId(event.target.value)} disabled={pending}><option value="">Curso em branco</option>{bases.map(base => <option key={base.id} value={base.id}>Copiar: {base.title}</option>)}</select></label><p className="education-form-description">A cópia mantém conteúdo, referências e critérios do plano publicado. As edições passam a pertencer a esta organização.</p>{error && <p className="form-error" role="alert">{error}</p>}<div className="education-dialog-actions"><button className="button button-primary" type="submit" disabled={pending}>{pending ? 'Criando…' : baseId ? 'Criar cópia independente' : 'Criar curso'}{baseId ? <Copy size={16} /> : <Plus size={16} />}</button></div></form></CourseDialog>;
}

function CourseEditor({ id, prefix, org, back }: { id: string; prefix: string; org: CourseOrg; back: () => void }) {
  const [record, setRecord] = useState<CourseRecord | null>(null); const [document, setDocument] = useState<CourseDocument | null>(null); const [versions, setVersions] = useState<Version[]>([]); const [assets, setAssets] = useState<CourseAsset[]>([]);
  const [dirty, setDirty] = useState(false); const [tab, setTab] = useState<'content' | 'settings' | 'publish'>('content'); const [selected, setSelected] = useState<{ moduleId: string; unitId?: string } | null>(null);
  const [pending, setPending] = useState(false); const [error, setError] = useState<string | null>(null); const [notice, setNotice] = useState<string | null>(null); const [attempt, setAttempt] = useState(0); const [assigning, setAssigning] = useState(false);
  const base = `${prefix}/${id}`;
  useEffect(() => { const controller = new AbortController(); setError(null); void Promise.all([apiJson<{ course: CourseRecord; versions: Version[] }>(base, { signal: controller.signal }), apiJson<{ assets: CourseAsset[] }>(`${base}/assets`, { signal: controller.signal })]).then(([result, materials]) => { setRecord(result.course); setDocument(result.course.draft); setVersions(result.versions); setAssets(materials.assets); setDirty(false); setSelected(previous => previous ?? (result.course.draft.modules[0] ? { moduleId: result.course.draft.modules[0].id } : null)); }).catch(loadError => { if (!controller.signal.aborted) setError(failure(loadError)); }); return () => controller.abort(); }, [base, attempt]);
  useEffect(() => { if (!dirty) return; const warn = (event: BeforeUnloadEvent) => { event.preventDefault(); }; const warnLink = (event: MouseEvent) => { const link = event.target instanceof Element ? event.target.closest('a[href]') : null; if (link instanceof HTMLAnchorElement && link.target !== '_blank' && link.origin === location.origin && link.pathname !== location.pathname && !window.confirm('Há alterações não salvas. Sair desta página sem salvar?')) { event.preventDefault(); event.stopPropagation(); } }; window.addEventListener('beforeunload', warn); window.document.addEventListener('click', warnLink, true); return () => { window.removeEventListener('beforeunload', warn); window.document.removeEventListener('click', warnLink, true); }; }, [dirty]);
  const update = (next: CourseDocument) => { setDocument(next); setDirty(true); setNotice(null); };
  function leave() { if (!dirty || window.confirm('Há alterações não salvas. Deseja sair sem salvar?')) back(); }
  function reload() { if (!dirty || window.confirm('Recarregar descarta as alterações não salvas. Deseja continuar?')) setAttempt(value => value + 1); }
  async function save() { if (!record || !document || pending) return; setPending(true); setError(null); setNotice(null); try { const result = await apiJson<{ course: CourseRecord }>(base, { method: 'PUT', body: { expectedRevision: record.draft_revision, document } }); setRecord(result.course); setDocument(result.course.draft); setDirty(false); setNotice('Rascunho salvo. Publique quando estiver pronto para os alunos.'); } catch (saveError) { setError(failure(saveError)); } finally { setPending(false); } }
  async function publish() { if (!record || dirty || pending) return; setPending(true); setError(null); setNotice(null); try { const result = await apiJson<{ version: { id: string; version: number } }>(`${base}/publish`, { method: 'POST', body: { expectedRevision: record.draft_revision } }); setNotice(`Versão ${result.version.version} publicada. As matrículas existentes conservam sua versão atual.`); setAttempt(value => value + 1); } catch (publishError) { setError(failure(publishError)); } finally { setPending(false); } }
  async function archive() { if (pending || !window.confirm('Arquivar este curso impede novas atribuições. As matrículas e versões existentes são preservadas. Continuar?')) return; setPending(true); setError(null); try { await apiJson(`${base}/archive`, { method: 'POST' }); setNotice('Curso arquivado. As versões publicadas foram preservadas.'); setAttempt(value => value + 1); } catch (archiveError) { setError(failure(archiveError)); } finally { setPending(false); } }
  if (!record || !document) return <><button className="organization-back" type="button" onClick={back}><ArrowLeft size={15} />Todos os cursos</button><CourseState error={error} retry={() => setAttempt(value => value + 1)} /></>;
  const selectedModule = document.modules.find(item => item.id === selected?.moduleId); const selectedUnit = selectedModule?.units.find(item => item.id === selected?.unitId);
  function changeModule(moduleId: string, patch: Partial<CourseDocument['modules'][number]>) { if (document) update({ ...document, modules: document.modules.map(item => item.id === moduleId ? { ...item, ...patch } : item) }); }
  function changeUnit(unit: CourseUnit) { if (selectedModule) changeModule(selectedModule.id, { units: selectedModule.units.map(item => item.id === unit.id ? unit : item) }); }
  function addModule() { const module = { id: makeId('modulo'), title: 'Novo módulo', introductionMarkdown: '', units: [] }; update({ ...document!, modules: [...document!.modules, module] }); setSelected({ moduleId: module.id }); }
  function addUnit(moduleId: string, kind: 'lesson' | 'review') { const module = document!.modules.find(item => item.id === moduleId)!; const unit = newUnit(kind); changeModule(moduleId, { units: [...module.units, unit] }); setSelected({ moduleId, unitId: unit.id }); }
  function removeModule(moduleId: string) { if (!window.confirm('Remover este módulo e suas unidades do rascunho? Versões publicadas serão preservadas.')) return; const removed = new Set(document!.modules.find(item => item.id === moduleId)!.units.map(item => item.id)); update({ ...document!, modules: document!.modules.filter(item => item.id !== moduleId).map(item => ({ ...item, units: item.units.map(unit => ({ ...unit, prerequisites: unit.prerequisites.filter(previous => !removed.has(previous)) })) })) }); setSelected(null); }
  function removeUnit(moduleId: string, unitId: string) { if (!window.confirm('Remover esta unidade do rascunho?')) return; update({ ...document!, modules: document!.modules.map(module => ({ ...module, units: module.units.filter(unit => unit.id !== unitId).map(unit => ({ ...unit, prerequisites: unit.prerequisites.filter(previous => previous !== unitId) })) })) }); setSelected({ moduleId }); }
  return <><button className="organization-back" type="button" onClick={leave}><ArrowLeft size={15} />Todos os cursos</button><div className="course-editor-top"><div><span className={`organization-status ${record.status === 'published' ? 'active' : 'suspended'}`}>{courseStatus[record.status]}</span><h2>{document.title}</h2><p>Revisão {record.draft_revision}{dirty ? ' · Há alterações não salvas' : ' · Rascunho salvo'} · {document.modules.length} {document.modules.length === 1 ? 'módulo' : 'módulos'} · {document.modules.reduce((sum, module) => sum + module.units.length, 0)} {document.modules.reduce((sum, module) => sum + module.units.length, 0) === 1 ? 'unidade' : 'unidades'}</p></div><button className="button button-primary" type="button" disabled={pending || !dirty} onClick={() => void save()}><Save size={17} />{pending ? 'Aguarde…' : 'Salvar rascunho'}</button></div>{notice && <div className="organization-inline-success" role="status"><CircleCheck size={17} />{notice}</div>}{error && <div className="form-error course-editor-error" role="alert"><span>{error}</span><button type="button" className="button button-secondary" disabled={pending} onClick={reload}>Recarregar versão salva</button></div>}<div className="education-tabs" aria-label="Editor do curso">{([{ id: 'content', label: 'Conteúdo e atividades' }, { id: 'settings', label: 'Regras da jornada' }, { id: 'publish', label: 'Publicação e alunos' }] as const).map(item => <button type="button" key={item.id} aria-pressed={tab === item.id} onClick={() => setTab(item.id)}>{item.label}</button>)}</div>
    {tab === 'content' && <div className="course-editor-layout"><aside className="course-outline"><div className="course-outline-heading"><h3>Estrutura do curso</h3><button type="button" className="icon-button" aria-label="Adicionar módulo" disabled={pending} onClick={addModule}><Plus size={18} /></button></div>{document.modules.map((module, moduleIndex) => <div className="course-outline-module" key={module.id}><div className="course-outline-module-title"><button type="button" aria-current={selected?.moduleId === module.id && !selected?.unitId ? 'true' : undefined} onClick={() => setSelected({ moduleId: module.id })}><span>{String(moduleIndex + 1).padStart(2, '0')}</span>{module.title}</button><div className="course-order-controls"><button type="button" aria-label={`Subir módulo ${module.title}`} disabled={pending || moduleIndex === 0} onClick={() => update({ ...document, modules: reorder(document.modules, moduleIndex, -1) })}><ArrowUp size={13} /></button><button type="button" aria-label={`Descer módulo ${module.title}`} disabled={pending || moduleIndex === document.modules.length - 1} onClick={() => update({ ...document, modules: reorder(document.modules, moduleIndex, 1) })}><ArrowDown size={13} /></button></div></div>{module.units.map((unit, index) => <div className="course-outline-unit" key={unit.id}><button type="button" aria-current={selected?.unitId === unit.id ? 'true' : undefined} onClick={() => setSelected({ moduleId: module.id, unitId: unit.id })}>{unit.kind === 'review' ? <RefreshCw size={13} /> : <FileText size={13} />}<span>{unit.title}</span></button><div className="course-order-controls"><button type="button" aria-label={`Subir unidade ${unit.title}`} disabled={pending || index === 0} onClick={() => changeModule(module.id, { units: reorder(module.units, index, -1) })}><ArrowUp size={12} /></button><button type="button" aria-label={`Descer unidade ${unit.title}`} disabled={pending || index === module.units.length - 1} onClick={() => changeModule(module.id, { units: reorder(module.units, index, 1) })}><ArrowDown size={12} /></button></div></div>)}<div className="course-outline-add"><button type="button" disabled={pending} onClick={() => addUnit(module.id, 'lesson')}><Plus size={12} />Aula</button><button type="button" disabled={pending} onClick={() => addUnit(module.id, 'review')}><Plus size={12} />Revisão</button></div></div>)}{document.modules.length === 0 && <p>Adicione o primeiro módulo para começar.</p>}</aside><div className="course-editor-main">{selectedUnit && selectedModule ? <UnitEditor key={selectedUnit.id} unit={selectedUnit} allUnits={document.modules.flatMap(module => module.units)} assets={assets} base={base} update={changeUnit} assetAdded={asset => setAssets(current => [...current, asset])} remove={() => removeUnit(selectedModule.id, selectedUnit.id)} disabled={pending} uploadBusy={setPending} creditName={creditLabel(org)} creditSingular={singularCreditLabel(org)} /> : selectedModule ? <div className="organization-form course-form course-module-editor"><span className="eyebrow">MÓDULO</span><label>Título do módulo<input aria-label="Título do módulo" value={selectedModule.title} maxLength={160} onChange={event => changeModule(selectedModule.id, { title: event.target.value })} disabled={pending} /></label><label>Apresentação do módulo<textarea aria-label="Apresentação do módulo" value={selectedModule.introductionMarkdown} maxLength={30000} onChange={event => changeModule(selectedModule.id, { introductionMarkdown: event.target.value })} disabled={pending} rows={7} /></label><div className="course-module-actions"><button type="button" className="button button-primary" disabled={pending} onClick={() => addUnit(selectedModule.id, 'lesson')}><Plus size={16} />Adicionar aula</button><button type="button" className="button button-secondary" disabled={pending} onClick={() => addUnit(selectedModule.id, 'review')}><RefreshCw size={16} />Adicionar revisão</button><button type="button" className="button button-text" disabled={pending} onClick={() => removeModule(selectedModule.id)}><Trash2 size={15} />Remover módulo</button></div>{selectedModule.introductionMarkdown && <details className="course-form-preview"><summary>Prévia da apresentação</summary><MarkdownContent text={selectedModule.introductionMarkdown} /></details>}</div> : <div className="course-editor-empty"><Layers3 size={32} /><h3>Escolha uma parte do curso para editar.</h3><p>A estrutura ao lado acompanha a ordem em que o conteúdo será apresentado.</p><button className="button button-primary" type="button" disabled={pending} onClick={addModule}><Plus size={16} />Adicionar módulo</button></div>}</div></div>}
    {tab === 'settings' && <CourseSettings document={document} update={update} disabled={pending} creditName={creditLabel(org)} />}
    {tab === 'publish' && <div className="course-publish-layout"><article className="course-publish-card"><span className="feature-icon icon-green"><GraduationCap size={25} /></span><h3>Do rascunho para a jornada.</h3><p>Uma publicação conserva conteúdo, critérios e regras. Alunos já matriculados continuam na versão atribuída a eles.</p>{dirty && <p className="form-notice">Salve as alterações antes de publicar ou atribuir o curso.</p>}<button type="button" className="button button-primary" disabled={pending || dirty} onClick={() => void publish()}>{pending ? 'Publicando…' : 'Publicar versão'}<Check size={17} /></button><button type="button" className="button button-secondary" disabled={pending || dirty || record.status !== 'published' || versions.length === 0} onClick={() => setAssigning(true)}><Users size={16} />Atribuir a alunos ou turma</button>{record.status !== 'archived' && <button type="button" className="button button-text" disabled={pending || dirty} onClick={() => void archive()}>Arquivar curso</button>}</article><article className="course-version-history"><h3>Versões publicadas</h3>{versions.length === 0 ? <p>Nenhuma versão publicada ainda.</p> : versions.map(version => <div key={version.id}><span className="course-version-number">{version.version}</span><div><strong>Versão {version.version}</strong><span>{formatDate(version.published_at)}</span></div><span>Preservada</span></div>)}</article></div>}
    {assigning && <CourseAssignment base={base} versions={versions} close={() => setAssigning(false)} completed={message => { setNotice(message); setAssigning(false); }} />}
  </>;
}

function LineListEditor({ values, update, disabled }: { values: string[]; update: (values: string[]) => void; disabled: boolean }) {
  const [text, setText] = useState(values.join('\n'));
  return <label>Checklist · um item por linha<textarea aria-label="Checklist da unidade" value={text} rows={5} disabled={disabled} maxLength={200000} onChange={event => { setText(event.target.value); update(event.target.value.split('\n').map(item => item.trim()).filter(Boolean)); }} /><small>Até 100 itens. Descreva ações concretas que o aluno pode conferir.</small></label>;
}
function UnitEditor({ unit, allUnits, assets, base, update, assetAdded, remove, disabled, uploadBusy, creditName, creditSingular }: { unit: CourseUnit; allUnits: CourseUnit[]; assets: CourseAsset[]; base: string; update: (unit: CourseUnit) => void; assetAdded: (asset: CourseAsset) => void; remove: () => void; disabled: boolean; uploadBusy: (busy: boolean) => void; creditName: string; creditSingular: string }) {
  const [tab, setTab] = useState<'lesson' | 'practice' | 'rubric' | 'preview'>('lesson'); const [uploading, setUploading] = useState(false); const [uploadError, setUploadError] = useState<string | null>(null);
  const latest = useRef(unit); latest.current = unit;
  const patch = (value: Partial<CourseUnit>) => update({ ...unit, ...value });
  const activity = (value: Partial<CourseUnit['activity']>) => patch({ activity: { ...unit.activity, ...value } });
  async function upload(file?: File) {
    if (!file || uploading) return; setUploadError(null);
    if (file.size === 0 || file.size > 200 * 1024 * 1024 || file.type === 'application/pdf' && file.size > 20 * 1024 * 1024) { setUploadError('Envie PDF de até 20 MB ou imagem, áudio ou vídeo de até 200 MB.'); return; }
    setUploading(true); uploadBusy(true); const body = new FormData(); body.append('file', file); const controller = new AbortController(); const timeout = window.setTimeout(() => controller.abort(), 120000);
    try { const response = await fetch(`${base}/assets`, { method: 'POST', body, credentials: 'same-origin', mode: 'same-origin', headers: { 'x-matraca-request': '1', Accept: 'application/json' }, signal: controller.signal }); const result = await response.json() as { asset?: CourseAsset; error?: string }; if (!response.ok || !result.asset) throw new ApiError(response.status, result.error && result.error.length <= 300 ? result.error : 'Não foi possível enviar o material.'); assetAdded(result.asset); update({ ...latest.current, assetIds: [...latest.current.assetIds, result.asset.id] }); }
    catch (uploadFailure) { setUploadError(uploadFailure instanceof ApiError ? uploadFailure.message : 'O envio não foi confirmado. Verifique a conexão e tente novamente.'); } finally { window.clearTimeout(timeout); setUploading(false); uploadBusy(false); }
  }
  const busy = disabled || uploading;
  return <div className="course-unit-editor"><div className="course-unit-editor-heading"><span className="eyebrow">{unit.kind === 'review' ? 'REVISÃO' : 'AULA'}</span><button type="button" className="button button-text" disabled={busy} onClick={remove}><Trash2 size={14} />Remover unidade</button></div><div className="course-unit-tabs">{([{ id: 'lesson', label: 'Conteúdo' }, { id: 'practice', label: 'Prática' }, { id: 'rubric', label: 'Critérios' }, { id: 'preview', label: 'Prévia' }] as const).map(item => <button type="button" key={item.id} aria-pressed={tab === item.id} onClick={() => setTab(item.id)}>{item.label}</button>)}</div>
    {tab === 'lesson' && <fieldset disabled={busy} className="organization-form course-form course-unit-fields"><label>Título da unidade<input aria-label="Título da unidade" value={unit.title} maxLength={160} onChange={event => patch({ title: event.target.value })} /></label><div className="course-form-grid"><label>Tipo<select aria-label="Tipo da unidade" value={unit.kind} onChange={event => patch({ kind: event.target.value as 'lesson' | 'review' })}><option value="lesson">Aula</option><option value="review">Revisão do módulo</option></select></label><label>Capítulo opcional<input aria-label="Capítulo da unidade" value={unit.chapter} maxLength={160} onChange={event => patch({ chapter: event.target.value })} /></label></div><label>Formato<select aria-label="Formato da unidade" value={unit.mode} onChange={event => patch({ mode: event.target.value as 'content' | 'tracking' })}><option value="content">Conteúdo e prática na plataforma</option><option value="tracking">Acompanhamento de prática</option></select></label><p className="course-field-note">No acompanhamento, a aula pode acontecer fora da plataforma. A unidade mantém instruções, critérios e registro da prática.</p>{unit.mode === 'content' && <label>Conteúdo da aula<textarea aria-label="Conteúdo da aula" value={unit.bodyMarkdown} maxLength={100000} rows={16} onChange={event => patch({ bodyMarkdown: event.target.value })} /><small>Use títulos, listas e links em Markdown. Confira o resultado na prévia.</small></label>}<LineListEditor values={unit.checklist} update={checklist => patch({ checklist })} disabled={busy} /><div className="course-field-section"><div className="course-field-section-heading"><h3>Referências</h3><button type="button" className="button button-secondary" onClick={() => patch({ references: [...unit.references, { title: '', href: '' }] })} disabled={unit.references.length >= 100}><Plus size={14} />Adicionar</button></div>{unit.references.map((reference, index) => <div className="course-reference-edit" key={index}><label>Título<input aria-label={`Título da referência ${index + 1}`} value={reference.title} maxLength={300} onChange={event => patch({ references: unit.references.map((item, position) => position === index ? { ...item, title: event.target.value } : item) })} /></label><label>Endereço<input aria-label={`Endereço da referência ${index + 1}`} value={reference.href} maxLength={2000} onChange={event => patch({ references: unit.references.map((item, position) => position === index ? { ...item, href: event.target.value } : item) })} placeholder="https://" /></label><button type="button" className="icon-button" aria-label={`Remover referência ${index + 1}`} onClick={() => patch({ references: unit.references.filter((_, position) => position !== index) })}><X size={16} /></button></div>)}</div><div className="course-field-section"><h3>Materiais de apoio</h3><p className="course-field-note">PDF e slides em PDF: até 20 MB. Imagem, áudio ou vídeo: até 200 MB. Áudio e vídeo: até 60 minutos.</p><label className="course-upload"><Upload size={20} /><span>{uploading ? 'Enviando material…' : 'Selecionar material'}<small>O material será anexado a esta unidade.</small></span><input aria-label="Enviar material da aula" type="file" accept="application/pdf,image/png,image/jpeg,image/webp,audio/*,video/*" onChange={event => { void upload(event.target.files?.[0]); event.target.value = ''; }} /></label>{uploadError && <p className="form-error" role="alert">{uploadError}</p>}{unit.assetIds.map(id => <div className="course-attached-file" key={id}><FileText size={16} /><a href={`/api/course-assets/${id}`} target="_blank" rel="noreferrer">{assets.find(item => item.id === id)?.filename ?? 'Material anexado'}<ExternalLink size={12} /></a><button type="button" className="icon-button" aria-label={`Desvincular ${assets.find(item => item.id === id)?.filename ?? 'material'}`} onClick={() => patch({ assetIds: unit.assetIds.filter(assetId => assetId !== id) })}><X size={15} /></button></div>)}{assets.some(asset => !unit.assetIds.includes(asset.id)) && <label>Reutilizar material deste curso<select aria-label="Reutilizar material" value="" onChange={event => { if (event.target.value) patch({ assetIds: [...unit.assetIds, event.target.value] }); }}><option value="">Selecione um material já enviado</option>{assets.filter(asset => !unit.assetIds.includes(asset.id)).map(asset => <option key={asset.id} value={asset.id}>{asset.filename}</option>)}</select></label>}</div></fieldset>}
    {tab === 'practice' && <fieldset disabled={busy} className="organization-form course-form course-unit-fields"><label>Orientação para a prática<textarea aria-label="Orientação da prática" value={unit.instructionMarkdown} maxLength={30000} rows={8} onChange={event => patch({ instructionMarkdown: event.target.value })} /></label><div className="course-form-grid"><label>Duração máxima em segundos<input aria-label="Duração máxima da prática" type="number" min={1} max={1800} step={1} value={unit.activity.maximumSeconds} onChange={event => activity({ maximumSeconds: Number(event.target.value) })} /></label><label>{creditName} ao estudar a unidade<input aria-label="Créditos da unidade" type="number" min={0} max={10000} step={1} value={unit.studyCreditGrant} onChange={event => patch({ studyCreditGrant: Number(event.target.value) })} /></label></div><p className="course-field-note">A recompensa por estudo prepara saldo para a avaliação. O consumo arredonda cada minuto iniciado para cima.</p><div className="course-media-options"><strong>Formatos aceitos</strong>{(['audio', 'video'] as const).map(media => <label key={media}><input type="checkbox" checked={unit.activity.acceptedMedia.includes(media)} onChange={event => activity({ acceptedMedia: event.target.checked ? [...unit.activity.acceptedMedia, media] : unit.activity.acceptedMedia.filter(item => item !== media) })} />{media === 'audio' ? 'Áudio' : 'Vídeo'}</label>)}</div><label>Cenário de prática<select aria-label="Cenário da prática" value={unit.activity.scenario} onChange={event => activity({ scenario: event.target.value as CourseUnit['activity']['scenario'] })}><option value="one_on_one">Conversa a dois</option><option value="executive">Reunião executiva</option><option value="audience">Apresentação para uma plateia</option></select></label><label className="course-toggle"><span>Exigir avaliação para concluir esta unidade</span><input type="checkbox" checked={unit.requiresEvaluation} onChange={event => patch({ requiresEvaluation: event.target.checked })} /></label><label>Pré-requisitos<select aria-label="Pré-requisitos da unidade" multiple value={unit.prerequisites} onChange={event => patch({ prerequisites: Array.from(event.target.selectedOptions, option => option.value) })}>{allUnits.filter(item => item.id !== unit.id).map(item => <option key={item.id} value={item.id}>{item.title}</option>)}</select><small>Selecione as unidades que precisam ser concluídas antes desta. Use Ctrl ou ⌘ para selecionar mais de uma.</small></label></fieldset>}
    {tab === 'rubric' && <fieldset disabled={busy} className="organization-form course-form course-unit-fields"><div className="course-field-section-heading"><div><h3>Critérios desta prática</h3><p className="course-field-note">Descreva comportamentos observáveis em quatro níveis.</p></div><button type="button" className="button button-secondary" disabled={unit.activity.criteria.length >= 40} onClick={() => activity({ criteria: [...unit.activity.criteria, newCriterion()] })}><Plus size={14} />Critério</button></div>{unit.activity.criteria.map((criterion, index) => <details className="course-criterion-editor" key={criterion.id}><summary><span>{criterion.title || `Critério ${index + 1}`}</span><small>{criterion.enabled ? `Peso ${criterion.weight}` : 'Desativado'}</small></summary><div><label>Nome do critério<input aria-label={`Nome do critério ${index + 1}`} maxLength={160} value={criterion.title} onChange={event => activity({ criteria: unit.activity.criteria.map((item, position) => position === index ? { ...item, title: event.target.value } : item) })} /></label><div className="course-form-grid"><label>Peso<input type="number" aria-label={`Peso do critério ${index + 1}`} min={0} max={1000} value={criterion.weight} onChange={event => activity({ criteria: unit.activity.criteria.map((item, position) => position === index ? { ...item, weight: Number(event.target.value) } : item) })} /></label><label>Observável em<select aria-label={`Modalidade do critério ${index + 1}`} value={criterion.modality} onChange={event => activity({ criteria: unit.activity.criteria.map((item, position) => position === index ? { ...item, modality: event.target.value as 'audio' | 'visual' | 'both' } : item) })}><option value="both">Áudio e vídeo</option><option value="audio">Áudio</option><option value="visual">Imagem do vídeo</option></select></label></div><label className="course-toggle"><span>Incluir este critério na avaliação</span><input type="checkbox" checked={criterion.enabled} onChange={event => activity({ criteria: unit.activity.criteria.map((item, position) => position === index ? { ...item, enabled: event.target.checked } : item) })} /></label>{criterion.descriptors.map((description, level) => <label key={level}>Nível {level + 1}<textarea aria-label={`Descritor do critério ${index + 1}, nível ${level + 1}`} value={description} rows={3} maxLength={1000} onChange={event => activity({ criteria: unit.activity.criteria.map((item, position) => position === index ? { ...item, descriptors: item.descriptors.map((value, descriptor) => descriptor === level ? event.target.value : value) as [string, string, string, string] } : item) })} /></label>)}<button type="button" className="button button-text" disabled={unit.activity.criteria.length <= 1} onClick={() => activity({ criteria: unit.activity.criteria.filter((_, position) => position !== index) })}><Trash2 size={14} />Remover critério</button></div></details>)}</fieldset>}
    {tab === 'preview' && <div className="course-unit-preview"><span className="course-preview-badge">Prévia do rascunho</span><CourseUnitContent unit={unit} assets={assets} creditName={creditName} creditSingular={creditSingular} /></div>}
  </div>;
}

function CourseSettings({ document, update, disabled, creditName }: { document: CourseDocument; update: (document: CourseDocument) => void; disabled: boolean; creditName: string }) {
  const patch = (value: Partial<CourseDocument>) => update({ ...document, ...value });
  return <fieldset disabled={disabled} className="organization-form course-form course-settings"><div><h3>Identidade do programa</h3><label>Título do curso<input aria-label="Título do curso" value={document.title} maxLength={160} onChange={event => patch({ title: event.target.value })} /></label><label>Descrição<textarea aria-label="Descrição do curso" value={document.description} maxLength={3000} rows={4} onChange={event => patch({ description: event.target.value })} /></label><label>Organização da jornada<select aria-label="Organização da jornada" value={document.journey} onChange={event => patch({ journey: event.target.value as 'adaptive' | 'sequential' })}><option value="sequential">Sequencial · seguir a ordem do curso</option><option value="adaptive">Adaptativa · orientar pelas necessidades do aluno</option></select></label><p className="course-field-note">A preferência da organização por jornada obrigatória prevalece sobre a opção adaptativa.</p><label className="course-toggle"><span>Exibir o curso no catálogo da organização</span><input type="checkbox" checked={document.catalogVisible} onChange={event => patch({ catalogVisible: event.target.checked })} /></label></div><div><h3>Recompensas de aprendizagem</h3><label>Liberação de {creditName}<select aria-label="Liberação de créditos do curso" value={document.creditMode} onChange={event => patch({ creditMode: event.target.value as 'progress' | 'acquisition' })}><option value="progress">Conforme o progresso nas unidades</option><option value="acquisition">Na aquisição do curso</option></select></label>{document.creditMode === 'acquisition' ? <label>{creditName} incluídos na aquisição<input aria-label="Créditos na aquisição" type="number" min={0} max={10000} step={1} value={document.acquisitionCredits} onChange={event => patch({ acquisitionCredits: Number(event.target.value) })} /></label> : <p className="course-field-note">Configure a recompensa de cada aula e revisão na aba Prática da unidade.</p>}<label>Recompensa ao concluir o curso<input aria-label="Créditos ao concluir curso" type="number" min={0} max={10000} step={1} value={document.completionCreditGrant} onChange={event => patch({ completionCreditGrant: Number(event.target.value) })} /></label><p className="course-field-note">Cada marco de aprendizagem tem uma concessão própria. Repetir o mesmo marco não multiplica a recompensa.</p></div><div className="course-settings-wide"><h3>Apresentação e orientações gerais</h3><label>Introdução do curso<textarea aria-label="Introdução do curso" value={document.introductionMarkdown} maxLength={100000} rows={8} onChange={event => patch({ introductionMarkdown: event.target.value })} /></label><label>Apêndices e referências gerais<textarea aria-label="Apêndices do curso" value={document.appendicesMarkdown} maxLength={100000} rows={8} onChange={event => patch({ appendicesMarkdown: event.target.value })} /></label>{document.provenance && <div className="course-provenance"><BookOpen size={18} /><p>Este curso preserva uma cópia integral de sua fonte de origem. Os conteúdos e as referências podem ser adaptados nesta organização sem alterar o plano original.</p></div>}</div></fieldset>;
}

function CourseAssignment({ base, versions, close, completed }: { base: string; versions: Version[]; close: () => void; completed: (message: string) => void }) {
  const [versionId, setVersionId] = useState(versions[0]?.id ?? ''); const [kind, setKind] = useState<'student' | 'class'>('student'); const [search, setSearch] = useState(''); const [page, setPage] = useState(1); const [target, setTarget] = useState('');
  const [result, setResult] = useState<{ items: { id: string; name: string; detail: string }[]; total: number; pageSize: number } | null>(null); const [error, setError] = useState<string | null>(null); const [pending, setPending] = useState(false); const [attempt, setAttempt] = useState(0);
  useEffect(() => { const controller = new AbortController(); setError(null); const timer = window.setTimeout(() => { const query = new URLSearchParams({ kind, search, page: String(page), pageSize: '8' }); void apiJson<{ items: { id: string; name: string; detail: string }[]; total: number; pageSize: number }>(`${base}/assignable?${query}`, { signal: controller.signal }).then(setResult).catch(loadError => { if (!controller.signal.aborted) setError(failure(loadError)); }); }, 180); return () => { controller.abort(); window.clearTimeout(timer); }; }, [base, kind, search, page, attempt]);
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!target || !versionId) return; setPending(true); setError(null); try { const response = await apiJson<{ enrolled: number }>(`${base}/assign`, { method: 'POST', body: { versionId, [kind === 'student' ? 'studentId' : 'classId']: target } }); completed(`Atribuição registrada. ${response.enrolled} ${response.enrolled === 1 ? 'nova matrícula criada' : 'novas matrículas criadas'}. Alunos já inscritos mantêm a versão anterior.`); } catch (saveError) { setError(failure(saveError)); setPending(false); } }
  return <CourseDialog title="Atribuir curso" close={close} pending={pending}><form className="organization-form course-form education-action-form" onSubmit={submit}><label>Versão publicada<select aria-label="Versão para atribuir" value={versionId} onChange={event => setVersionId(event.target.value)} disabled={pending}>{versions.map(version => <option key={version.id} value={version.id}>Versão {version.version} · {formatDate(version.published_at)}</option>)}</select></label><label>Destino<select aria-label="Tipo de atribuição" value={kind} disabled={pending} onChange={event => { setKind(event.target.value as 'student' | 'class'); setResult(null); setTarget(''); setPage(1); setSearch(''); }}><option value="student">Aluno individual</option><option value="class">Turma</option></select></label><label>Buscar {kind === 'student' ? 'aluno' : 'turma'}<input type="search" aria-label="Buscar destinatário do curso" value={search} maxLength={100} disabled={pending} onChange={event => { setSearch(event.target.value); setPage(1); setTarget(''); }} placeholder="Digite para filtrar" /></label><div className="course-assignment-options">{!result && <p>Consultando destinatários…</p>}{result?.items.map(item => <label key={item.id}><input type="radio" name="assignment-target" value={item.id} checked={target === item.id} disabled={pending} onChange={() => setTarget(item.id)} /><span><strong>{item.name}</strong><small>{item.detail}</small></span></label>)}{result?.items.length === 0 && <p>Nenhum destinatário encontrado.</p>}</div>{result && <div className="course-assignment-pagination"><span>{result.total} resultados · página {page}</span><button type="button" aria-label="Destinatários anteriores" className="icon-button" disabled={pending || page === 1} onClick={() => { setPage(value => value - 1); setTarget(''); }}><ChevronLeft size={16} /></button><button type="button" aria-label="Próximos destinatários" className="icon-button" disabled={pending || page * result.pageSize >= result.total} onClick={() => { setPage(value => value + 1); setTarget(''); }}><ChevronRight size={16} /></button></div>}{kind === 'class' && <p className="course-field-note">A atribuição inclui alunos atuais e novas matrículas desta turma. Quem já tem este curso mantém sua versão.</p>}{error && <div className="form-error" role="alert">{error}<button type="button" className="button button-text" onClick={() => setAttempt(value => value + 1)}>Reconsultar lista</button></div>}<div className="education-dialog-actions"><button className="button button-primary" type="submit" disabled={pending || !target}>{pending ? 'Atribuindo…' : 'Confirmar atribuição'}<Check size={16} /></button></div></form></CourseDialog>;
}

export function StudentCoursesPage() { return <AuthenticatedArea area="learner"><StudentCourses /></AuthenticatedArea>; }
function StudentCourses() {
  const { org } = useAuth(); const { courseId } = useParams();
  const [courses, setCourses] = useState<StudentCourse[] | null>(null); const [enabled, setEnabled] = useState(true); const [error, setError] = useState<string | null>(null); const [attempt, setAttempt] = useState(0);
  useEffect(() => { const controller = new AbortController(); setError(null); void apiJson<{ enabled: boolean; courses: StudentCourse[] }>('/api/courses', { signal: controller.signal }).then(result => { setCourses(result.courses); setEnabled(result.enabled); }).catch(loadError => { if (!controller.signal.aborted) setError(failure(loadError)); }); return () => controller.abort(); }, [attempt]);
  if (courseId && enabled && org?.settings.coursesEnabled !== false) return <StudentCourseReader key={courseId} id={courseId} />;
  return <section className="courses-page container"><div className="organization-heading"><div><span className="eyebrow">{org?.name}</span><h1>Aprenda uma habilidade. Experimente sua voz.</h1><p>Seus cursos conectam conteúdo, intenção e prática.</p></div><LogoutButton /></div>{!courses || error ? <CourseState error={error} retry={() => setAttempt(value => value + 1)} /> : !enabled ? <div className="wallet-selection-empty"><BookOpen size={32} /><h2>Os cursos estão desativados neste espaço.</h2><p>Seu histórico e sua carteira continuam disponíveis.</p><Link className="button button-secondary" to="/app/wallet">Acessar minha carteira<ArrowRight size={16} /></Link></div> : courses.length === 0 ? <div className="wallet-selection-empty"><GraduationCap size={32} /><h2>Seu próximo curso aparecerá aqui.</h2><p>Quando um programa for atribuído a você, os módulos e materiais ficarão neste espaço.</p></div> : <div className="course-catalog-grid">{courses.map(course => <Link className="course-catalog-card" key={course.id} to={`/app/courses/${course.id}`}><span className="feature-icon icon-green"><BookOpen size={25} /></span><span className="course-enrolled-badge">Versão {course.version}</span><h3>{course.title}</h3><p>{course.description || 'Conteúdo e prática para sua jornada de oratória.'}</p><span className="course-open-label">Explorar o curso<ArrowRight size={17} /></span></Link>)}</div>}</section>;
}
function StudentCourseReader({ id }: { id: string }) {
  const { org } = useAuth(); const [detail, setDetail] = useState<StudentDetail | null>(null); const [error, setError] = useState<string | null>(null); const [attempt, setAttempt] = useState(0); const [selected, setSelected] = useState<string | null>(null); const [general, setGeneral] = useState<'introduction' | 'appendices'>('introduction');
  useEffect(() => { const controller = new AbortController(); setError(null); void apiJson<StudentDetail>(`/api/courses/${id}`, { signal: controller.signal }).then(setDetail).catch(loadError => { if (!controller.signal.aborted) setError(failure(loadError)); }); return () => controller.abort(); }, [id, attempt]);
  const unit = detail?.document.modules.flatMap(module => module.units).find(item => item.id === selected);
  return <section className="courses-page container"><Link className="organization-back" to="/app/courses"><ArrowLeft size={15} />Meus cursos</Link>{!detail || error ? <CourseState error={error} retry={() => setAttempt(value => value + 1)} /> : <><div className="course-reader-heading"><span className="eyebrow">SEU PROGRAMA DE ENSINO · VERSÃO {detail.version}</span><h1>{detail.document.title}</h1><p>{detail.document.description}</p></div><div className="course-reader-layout"><aside className="course-reader-outline"><button type="button" className="course-reader-intro" aria-pressed={!selected && general === 'introduction'} onClick={() => { setSelected(null); setGeneral('introduction'); }}><BookOpen size={16} />Conheça a jornada</button>{detail.document.modules.map((module, index) => <details key={module.id} open={index === 0 || module.units.some(item => item.id === selected)}><summary><span>{String(index + 1).padStart(2, '0')}</span>{module.title}</summary>{module.units.map(item => <button type="button" key={item.id} aria-current={item.id === selected ? 'true' : undefined} onClick={() => setSelected(item.id)}>{item.kind === 'review' ? <RefreshCw size={14} /> : <FileText size={14} />}<span>{item.title}</span></button>)}</details>)}{detail.document.appendicesMarkdown && <button type="button" className="course-reader-intro" aria-pressed={!selected && general === 'appendices'} onClick={() => { setSelected(null); setGeneral('appendices'); }}><FolderOpen size={16} />Orientações e referências</button>}</aside><article className="course-reader-main">{unit ? <CourseUnitContent unit={unit} assets={detail.assets ?? []} creditName={creditLabel(org)} creditSingular={singularCreditLabel(org)} /> : <><span className="eyebrow">{general === 'introduction' ? 'UM CAMINHO PARA A SUA VOZ' : 'PARA CONSULTAR E APROFUNDAR'}</span><h2>{general === 'introduction' ? 'Conheça a jornada.' : 'Orientações e referências.'}</h2>{(general === 'introduction' ? detail.document.introductionMarkdown : detail.document.appendicesMarkdown) ? <MarkdownContent text={general === 'introduction' ? detail.document.introductionMarkdown : detail.document.appendicesMarkdown} /> : <p>Selecione uma aula para consultar o conteúdo e a prática proposta.</p>}</>}{unit && <div className="course-next-phase"><GraduationCap size={19} /><p>O registro de progresso e o envio de práticas estão em construção na próxima etapa do piloto.</p></div>}</article></div></>}</section>;
}

function SchoolCourseManagement() {
  const { org } = useAuth();
  const [courses, setCourses] = useState<CourseSummary[] | null>(null); const [selected, setSelected] = useState<string | null>(null); const [detail, setDetail] = useState<{ course: { id: string; title: string; status: string }; versions: Version[] } | null>(null);
  const [error, setError] = useState<string | null>(null); const [notice, setNotice] = useState<string | null>(null); const [attempt, setAttempt] = useState(0); const [assigning, setAssigning] = useState(false);
  useEffect(() => { const controller = new AbortController(); setError(null); void apiJson<{ courses: CourseSummary[] }>('/api/courses/school', { signal: controller.signal }).then(result => setCourses(result.courses)).catch(loadError => { if (!controller.signal.aborted) setError(failure(loadError)); }); return () => controller.abort(); }, [attempt]);
  useEffect(() => { setDetail(null); if (!selected) return; const controller = new AbortController(); setError(null); void apiJson<{ course: { id: string; title: string; status: string }; versions: Version[] }>(`/api/courses/school/${selected}`, { signal: controller.signal }).then(setDetail).catch(loadError => { if (!controller.signal.aborted) setError(failure(loadError)); }); return () => controller.abort(); }, [selected, attempt]);
  return <section className="courses-page container"><div className="organization-heading"><div><span className="eyebrow">{org?.name}</span><h1>Leve cada programa às suas turmas.</h1><p>Atribua os cursos publicados pela organização aos alunos da sua escola.</p></div><LogoutButton /></div>{notice && <div className="organization-inline-success" role="status"><CircleCheck size={17} />{notice}</div>}{selected ? <><button className="organization-back" type="button" onClick={() => { setSelected(null); setError(null); }}><ArrowLeft size={15} />Todos os cursos</button>{!detail || error ? <CourseState error={error} retry={() => setAttempt(value => value + 1)} /> : <div className="course-publish-layout"><article className="course-publish-card"><span className="feature-icon icon-green"><GraduationCap size={25} /></span><h3>{detail.course.title}</h3><p>Selecione uma versão publicada e escolha um aluno ou uma turma sob sua gestão. A organização mantém o conteúdo e os critérios deste programa.</p><button className="button button-primary" type="button" disabled={detail.versions.length === 0} onClick={() => setAssigning(true)}><Users size={17} />Atribuir a alunos ou turma</button></article><article className="course-version-history"><h3>Versões disponíveis</h3>{detail.versions.map(version => <div key={version.id}><span className="course-version-number">{version.version}</span><div><strong>Versão {version.version}</strong><span>{formatDate(version.published_at)}</span></div></div>)}</article></div>}</> : !courses || error ? <CourseState error={error} retry={() => setAttempt(value => value + 1)} /> : courses.length === 0 ? <div className="wallet-selection-empty"><BookOpen size={32} /><h2>Os programas publicados aparecerão aqui.</h2><p>O administrador da organização prepara e publica o conteúdo para as escolas.</p></div> : <div className="course-catalog-grid">{courses.map(course => <button className="course-catalog-card" type="button" key={course.id} onClick={() => { setSelected(course.id); setNotice(null); }}><span className="feature-icon icon-green"><BookOpen size={25} /></span><span className="organization-status active">Publicado</span><h3>{course.title}</h3><p>Programa da organização disponível para os alunos da sua escola.</p><span className="course-open-label">Escolher destinatários<ArrowRight size={17} /></span></button>)}</div>}{assigning && detail && <CourseAssignment base={`/api/courses/school/${detail.course.id}`} versions={detail.versions} close={() => setAssigning(false)} completed={message => { setNotice(message); setAssigning(false); }} />}</section>;
}
